#!/usr/bin/env python3
import pathlib,tempfile,subprocess,json,hashlib,os
E=pathlib.Path(__file__).resolve().parent;R=E.parents[2];F=R/'migration/tests/color-exchange-foundation';sha=lambda b:hashlib.sha256(b).hexdigest();files=['app/painter/filter-color-exchange-private.hpp','app/painter/gimp-painter-visibility.h',*[str(p.relative_to(R))for p in [E/'kernel-bridge.cpp',E/'test-kernel.c',F/'test-oracle.c',F/'old-exchange.inc',F/'old-rgb.inc']]];report={'source_sha256':{n:sha((R/n).read_bytes())for n in files},'runs':{},'scope':'new pure typed kernel versus literal old exchange and independent equations; no native integration'}
with tempfile.TemporaryDirectory(prefix='color-exchange-kernel-')as td:
 D=pathlib.Path(td);fixture=(F/'test-oracle.c').read_text();assert fixture.count('static void oracle(')==1;fixture=fixture.replace('oracle(','checked_oracle(').replace('static void checked_oracle(','static void independent_oracle(',1);(D/'checked-fixture.inc').write_text(fixture);report['generated_fixture_sha256']=sha(fixture.encode())
 for mode,flags in [('normal',['-O2']),('sanitizer',['-O1','-g0','-fsanitize=address,undefined,float-cast-overflow','-fno-omit-frame-pointer'])]:
  c=D/(mode+'.o');cpp=D/(mode+'-cpp.o');exe=D/mode;commands=[['cc','-std=c11','-Wall','-Wextra','-Werror',*flags,'-I'+str(D),'-I'+str(F),'-c',str(E/'test-kernel.c'),'-o',str(c)],['c++','-std=c++14','-fno-rtti','-Wall','-Wextra','-Werror',*flags,'-I'+str(R),'-c',str(E/'kernel-bridge.cpp'),'-o',str(cpp)],['c++',*flags,str(c),str(cpp),'-lm','-o',str(exe)]]
  for cmd in commands:
   b=subprocess.run(cmd,capture_output=True,text=True);assert b.returncode==0,b.stderr
  env=dict(os.environ,ASAN_OPTIONS='detect_leaks=0:halt_on_error=1',UBSAN_OPTIONS='halt_on_error=1:print_stacktrace=1');q=subprocess.run([str(exe)],capture_output=True,text=True,timeout=120,env=env);report['runs'][mode]=dict(commands=commands,returncode=q.returncode,stdout=q.stdout,stderr=q.stderr,binary_sha256=sha(exe.read_bytes()));assert q.returncode==0,q.stderr;print(mode,q.stdout.strip())
 original=(R/'app/painter/filter-color-exchange-private.hpp').read_text();target=D/'app/painter';target.mkdir(parents=True);(target/'gimp-painter-visibility.h').write_bytes((R/'app/painter/gimp-painter-visibility.h').read_bytes());report['negative_controls']=[]
 mutations=[('exclusive-threshold','distance[c]>options.threshold[c]','distance[c]>=options.threshold[c]'),('partial-match','if(distance[c]>options.threshold[c])return pixel;','if(c==0 && distance[c]>options.threshold[c])return pixel;'),('signed-delta','unsigned(difference<0?-difference:difference)','unsigned(difference)'),('no-saturation','std::uint8_t(value>255?255:value)','std::uint8_t(value)'),('alpha-overwrite','  return pixel;\n}','  pixel[3]=255; return pixel;\n}')]
 for name,before,after in mutations:
  assert original.count(before)==1;mutant=original.replace(before,after);(target/'filter-color-exchange-private.hpp').write_text(mutant);obj=D/(name+'.o');exe=D/name;cmd=['c++','-std=c++14','-fno-rtti','-O2','-I'+str(D),'-I'+str(R),'-c',str(E/'kernel-bridge.cpp'),'-o',str(obj)];subprocess.run(cmd,check=True);subprocess.run(['c++',str(D/'normal.o'),str(obj),'-lm','-o',str(exe)],check=True);q=subprocess.run([str(exe)],capture_output=True,text=True,timeout=120);assert q.returncode!=0 and 'Assertion'in q.stderr,(name,q.stdout,q.stderr);report['negative_controls'].append(dict(name=name,returncode=q.returncode,stdout=q.stdout,stderr=q.stderr,mutant_sha256=sha(mutant.encode()),command=cmd));print('REJECT',name)
report['changed_sources']=[n for n,h in report['source_sha256'].items()if sha((R/n).read_bytes())!=h];assert not report['changed_sources'];(E/'results.json').write_text(json.dumps(report,indent=2)+'\n')
